// Validates a reminder-attempt request from an already-deciding orchestrator.
// Does NOT decide reminder cadence/policy -- that decision (which stage,
// whether it's worth attempting) lives entirely outside this workflow.
//
// recipientPhone/amount/currency/dueDate are NOT input fields -- read
// exclusively from Postgres (invoices) later in this workflow. Accepting
// them from the caller would let arbitrary caller-controlled data redirect
// or fabricate a reminder; Postgres is the source of truth for all of them.
//
// reminderStage is strictly allowlisted, not an arbitrary string -- it
// selects a trusted, hardcoded template/language pair later in this
// workflow (see Build Send Request), never caller-controlled template
// content.

const input = $input.first().json;

function isValidOpaqueId(v, maxLength) {
  return typeof v === 'string' && v.length >= 1 && v.length <= maxLength && /^[A-Za-z0-9_-]+$/.test(v);
}
function isValidReminderStage(v) {
  return v === 'stage1' || v === 'stage2' || v === 'final';
}
function isValidExpectedVersion(v) {
  return typeof v === 'number' && Number.isInteger(v) && v >= 1 && v <= 1000000000;
}

const idempotencyKey = input.idempotencyKey;
const invoiceId = input.invoiceId;
const reminderStage = input.reminderStage;
const expectedVersion = input.expectedVersion;

const idempotencyKeyValid = isValidOpaqueId(idempotencyKey, 128);
const invoiceIdValid = isValidOpaqueId(invoiceId, 128);
const reminderStageValid = isValidReminderStage(reminderStage);
const expectedVersionValid = isValidExpectedVersion(expectedVersion);

const valid = idempotencyKeyValid && invoiceIdValid && reminderStageValid && expectedVersionValid;

if (!valid) {
  return [{ json: {
    _route: 'rejected',
    invoiceId: invoiceIdValid ? invoiceId : null,
  } }];
}

return [{ json: {
  _route: 'valid',
  idempotencyKey, invoiceId, reminderStage, expectedVersion,
} }];

// Reached only when input validation failed -- zero database and zero
// sender-workflow calls were made, structurally guaranteed (this node only
// runs from the "Input Valid?" IF node's false output, before any Postgres
// or Execute Workflow node in this workflow).

const item = $input.first().json;
return [{ json: {
  status: 'rejected',
  invoiceId: item.invoiceId,
  reminderStage: null,
  httpStatus: null,
  providerMessageId: null,
} }];

// Classifies process_invoice_reminder(...)'s result. `route` is one of:
//   'owner_applied'       -- this call owns the idempotency reservation;
//                            result_status is the actual outcome (which
//                            may itself be terminal, or 'reminder_pending'
//                            if a sender call is still needed).
//   'duplicate_match'     -- idempotencyKey already reserved by an
//                            IDENTICAL prior request (same invoiceId and
//                            reminderStage) -- result_status is that prior
//                            request's real, durable outcome.
//   'idempotency_mismatch'-- idempotencyKey already reserved by a
//                            DIFFERENT request (different invoiceId or
//                            reminderStage) -- zero mutation of any
//                            invoice occurred for this call.
//
// Every route except "owner_applied with result_status = reminder_pending"
// is immediately terminal -- no sender call is ever reachable from this
// node except via that one specific path.

const result = $input.first().json;
const validated = $('Validate Input').first().json;

const needsSend = result.route === 'owner_applied' && result.result_status === 'reminder_pending';

return [{ json: {
  _route: needsSend ? 'needs_send' : 'finalized',
  resultStatus: result.result_status,
  idempotencyKey: validated.idempotencyKey,
  invoiceId: validated.invoiceId,
  reminderStage: validated.reminderStage,
  expectedVersion: validated.expectedVersion,
  recipientPhone: result.out_recipient_phone,
  amount: result.out_amount,
  currency: result.out_currency,
  dueDate: result.out_due_date,
} }];

// Reached for: duplicate replays, idempotency mismatches, missing
// invoices, version conflicts, paid/cancelled/disputed invoices,
// not-yet-due invoices, and already-reminded stages. None of these paths
// reach the sender sub-workflow -- structurally guaranteed by the IF node
// that routes here.

const classified = $('Classify Reserve Result').first().json;

return [{ json: {
  status: classified.resultStatus,
  invoiceId: classified.invoiceId,
  reminderStage: classified.reminderStage,
  httpStatus: null,
  providerMessageId: null,
} }];

// Builds the sender sub-workflow's request for confirmed-eligible
// reminders only -- reached only after Postgres durably recorded
// 'reminder_pending' for this (invoiceId, reminderStage) pair. The
// recipient phone comes EXCLUSIVELY from Postgres (read back from the
// atomic reservation call) -- never from caller input. templateName,
// languageCode, graphApiVersion, and phoneNumberId are all trusted,
// hardcoded configuration -- not caller input, not "reminder policy"
// arbitrarily chosen by whoever calls this workflow.

const c = $input.first().json;

// Replace with your own real WhatsApp Business phone number id before use.
const GRAPH_API_VERSION = 'v21.0';
const PHONE_NUMBER_ID = '000000000000000';

const STAGE_TEMPLATES = {
  stage1: { templateName: 'invoice_reminder_first', languageCode: 'en' },
  stage2: { templateName: 'invoice_reminder_second', languageCode: 'en' },
  final: { templateName: 'invoice_reminder_final', languageCode: 'en' },
};

const tpl = STAGE_TEMPLATES[c.reminderStage];

return [{ json: {
  idempotencyKey: c.idempotencyKey,
  invoiceId: c.invoiceId,
  reminderStage: c.reminderStage,
  expectedVersion: c.expectedVersion,
  recipientPhone: c.recipientPhone,
  templateName: tpl.templateName,
  languageCode: tpl.languageCode,
  graphApiVersion: GRAPH_API_VERSION,
  phoneNumberId: PHONE_NUMBER_ID,
  bodyParameters: [c.amount, c.currency, c.dueDate],
} }];

// Classifies the sender sub-workflow's own controlled output
// ({status, httpStatus, providerMessageId} -- see
// whatsapp-template-message-sender.json). Never trusts its shape blindly:
// an unexpected/malformed sender output degrades to a controlled failure,
// never a crash and never a false 'sent'.

const resp = $input.first().json;
const req = $('Build Send Request').first().json;

const outcome = resp.status === 'sent' ? 'sent' : 'failed';

return [{ json: {
  outcome,
  idempotencyKey: req.idempotencyKey,
  invoiceId: req.invoiceId,
  reminderStage: req.reminderStage,
  expectedVersion: req.expectedVersion,
  httpStatus: (typeof resp.httpStatus === 'number') ? resp.httpStatus : null,
  providerMessageId: (typeof resp.providerMessageId === 'string' && resp.providerMessageId.length > 0 && resp.providerMessageId.length <= 256) ? resp.providerMessageId : null,
} }];

// Reached after the version-guarded finalize write. If the guard didn't
// match (a newer invoice state already committed -- e.g. paid in the
// interim by whatever system owns payment status), the result is
// 'reconciliation_required' -- never falsely reported as full success --
// and the newer invoice row was never touched.

const finalizeResult = $input.first().json;
const classified = $('Classify Send Result').first().json;

return [{ json: {
  status: finalizeResult.out_result_status,
  invoiceId: classified.invoiceId,
  reminderStage: classified.reminderStage,
  httpStatus: classified.httpStatus,
  providerMessageId: classified.providerMessageId,
} }];
